  switch (art) {
    case "vorgaenge":
      return backend.vorgaenge(nutzer, { alle: true });
    case "flaechen":
      return backend.flaechen(nutzer, { alle: true });
    case "projekte":
      return backend.projekte(nutzer, { alle: true });
    case "interessen":
      return backend.interessen(nutzer, { alle: true });
